/**
 * The `cad` capability for enclosures (tool-integrations.md §2–§4), with
 * build123d.
 *
 *   generate  UHD module + assembly + cad.config.ts → native design in
 *             <module dir>/build123d/: <id>.job.json (the generator's
 *             inputs), <id>.py (the script that builds it, editable),
 *             <id>.report.json and <id>.source.json (what the build found,
 *             and the digests of the design it built) and build/ (the parts
 *             and body it built: a cache, regenerated by export)
 *   export    build/ → out/: body.step, body.glb, body.manifest.json, one
 *             STL and one 3MF per printed part, section.svg. Rebuilds first
 *             when the native design was edited since the last build.
 *   extract   the generated feature frames, by interface id, and the
 *             artifacts the module should reference
 *   check     drift, fit and feature checks (lib/check.ts)
 */
import { spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import type { ArtifactDef } from "@deltarobotics/uhd";
import { stableStringify, type CapabilityContext, type CapabilityOperationFn, type ExtractedFacts } from "@protoboardai/core";
import { checkEnclosure, nativePaths, readJson, type Fit, type Report } from "../lib/check.ts";
import { buildJob, type Job } from "../lib/job.ts";
import { coverArtifacts } from "../lib/features.ts";

export const PY_DIR = fileURLToPath(new URL("../py/", import.meta.url));
export const python = () => process.env.PROTOBOARD_PYTHON || "python3";
/** ext-harness-cad's py/ folder: its voxel obstacle map and GLB reader are shared, not copied. */
export const harnessPy = () => join(dirname(createRequire(import.meta.url).resolve("@protoboardai/ext-harness-cad/package.json")), "py");

const sha = (b: string | Buffer) => "sha256:" + createHash("sha256").update(b).digest("hex");

function env() {
  return { ...process.env, PYTHONHASHSEED: "0", PROTOBOARD_ENCLOSURE_CAD_PY: PY_DIR, PROTOBOARD_HARNESS_CAD_PY: harnessPy() };
}

/**
 * Run the generator's Python. Asynchronous on purpose: a build or fit takes
 * tens of seconds, and blocking the event loop that long stalls whatever
 * shares the process (the dev server, a test runner's worker RPC).
 */
function runPython(args: string[], cwd: string, input?: string): Promise<{ ok: true; stdout: string } | { ok: false; error: string }> {
  return new Promise((resolve) => {
    const child = spawn(python(), args, { cwd, env: env(), stdio: [input === undefined ? "ignore" : "pipe", "pipe", "pipe"], timeout: 900000 });
    let stdout = "";
    let stderr = "";
    child.stdout!.setEncoding("utf8").on("data", (d: string) => (stdout += d));
    child.stderr!.setEncoding("utf8").on("data", (d: string) => (stderr += d));
    if (input !== undefined) child.stdin!.end(input);
    child.on("error", (e) => resolve({ ok: false, error: e.message.split("\n")[0] }));
    child.on("close", (code, signal) => {
      if (code === 0) return resolve({ ok: true, stdout });
      const message = `${python()} exited with ${code ?? signal}`;
      resolve({ ok: false, error: (stderr || message).trim().split("\n").filter((l) => !/Warning|warnings\.warn|^\s/.test(l)).slice(-2).join(" | ") || message });
    });
  });
}

/** The native build script: loads the job next to it and builds into build/ (or the folder given). */
export function script(job: Job): string {
  return `"""${job.name}: enclosure for ${job.module}, generated by @protoboardai/ext-enclosure-cad.

The inputs are in ${job.name}.job.json: what goes inside (bodies placed in
this enclosure's coordinates), the features from the module's interfaces,
and the design values from cad.config.ts. Edit either file to change the
design by hand; \`protoboard check\` reports where it no longer matches the
model, and \`protoboard run cad:export\` rebuilds from it.

    PROTOBOARD_ENCLOSURE_CAD_PY=<ext-enclosure-cad>/py python ${job.name}.py [out-dir]
"""
import json
import os
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
GENERATOR = os.environ.get("PROTOBOARD_ENCLOSURE_CAD_PY")
if not GENERATOR:
    sys.exit("set PROTOBOARD_ENCLOSURE_CAD_PY to the py/ folder of @protoboardai/ext-enclosure-cad (protoboard run cad:export does this)")
sys.path.insert(0, GENERATOR)
from enclosure_cad import build  # noqa: E402

job = json.loads((HERE / "${job.name}.job.json").read_text())
report = build(job, Path(sys.argv[1]) if len(sys.argv) > 1 else HERE / "build", (HERE / job["root"]).resolve())
print(json.dumps({"name": report["name"], "problems": report["problems"], "fit": report["fit"]["bodies"]}))
`;
}

function files(dir: string, prefix = ""): string[] {
  if (!existsSync(dir)) return [];
  return readdirSync(dir)
    .sort()
    .flatMap((f) => (statSync(join(dir, f)).isDirectory() ? files(join(dir, f), `${prefix}${f}/`) : [`${prefix}${f}`]));
}

/** Run the native script into a scratch folder, then register everything it built under build/. */
async function buildNative(ctx: CapabilityContext): Promise<{ report?: Report; error?: string; files: number }> {
  const p = ctx.project;
  const paths = nativePaths(ctx.module.native, ctx.module.id);
  const scratch = join(p.root, ".protoboard", "cache", "enclosure-cad", ctx.module.id);
  rmSync(scratch, { recursive: true, force: true });
  mkdirSync(scratch, { recursive: true });
  const r = await runPython([join(p.root, paths.script), scratch], p.root);
  if (!r.ok) return { error: r.error, files: 0 };
  rmSync(join(p.root, paths.build), { recursive: true, force: true });
  // the report sits next to the job, outside build/, so a project that commits its native design and out/ can be checked without rebuilding
  const built = files(scratch).filter((f) => f !== "report.json");
  for (const f of built) ctx.writeOutput(`${paths.build}/${f}`, readFileSync(join(scratch, f)), `${ctx.module.id}: ${f}`);
  ctx.writeOutput(paths.report, readFileSync(join(scratch, "report.json")), `${ctx.module.id}: what the build found (cavity, features, walls, fit)`);
  const source = { script: sha(readFileSync(join(p.root, paths.script))), job: sha(readFileSync(join(p.root, paths.job))) };
  ctx.writeOutput(paths.source, stableStringify(source), "digests of the native design this build came from");
  rmSync(scratch, { recursive: true, force: true });
  return { report: JSON.parse(readFileSync(join(p.root, paths.report), "utf8")) as Report, files: built.length + 2 };
}

const fitSummary = (r: Report) => r.fit.bodies.map((b) => `${b.key} ${b.status}${b.min_clearance_mm !== undefined ? ` (${b.min_clearance_mm} mm)` : ""}`).join(", ");

export const generate: CapabilityOperationFn = async (ctx) => {
  const p = ctx.project;
  const def = ctx.module.definition;
  const binding = { constraints: ctx.constraints, process: ctx.process, native: ctx.module.native, module: def.id, instances: ctx.module.instances };
  const built = buildJob(p, binding, def, ctx.module.instance);
  if (!built.job || built.problems.length) return { status: "failed", summary: `${def.id}: ${built.problems[0] ?? "no job"}`, data: { problems: built.problems, notes: built.notes } };
  const job = built.job;
  const paths = nativePaths(ctx.module.native, def.id);
  ctx.writeOutput(paths.job, JSON.stringify(job, null, 2) + "\n", `${def.id}: generator inputs from the model, the assembly and cad.config.ts`);
  ctx.writeOutput(paths.script, script(job), `${def.id}: build123d build script`);
  const b = await buildNative(ctx);
  if (!b.report) return { status: "failed", summary: `${def.id}: generator failed: ${b.error}` };
  const r = b.report;
  for (const note of built.notes) ctx.log(note);
  ctx.log(`${def.id}: ${Object.keys(r.parts).join(", ")}; fit: ${fitSummary(r)}`);
  return {
    status: "succeeded",
    summary: `${def.id}: ${Object.keys(r.parts).length} part(s) (${Object.keys(r.parts).join(", ")}), ${Object.keys(r.features).length} feature(s); fit: ${fitSummary(r)}${r.problems.length ? `; ${r.problems.length} problem(s): ${r.problems[0]}` : ""}`,
    data: { native: ctx.module.native, parts: r.parts, cavity: r.cavity, overall: r.overall, features: Object.keys(r.features), problems: r.problems, notes: built.notes, fit: r.fit, toolVersion: r.toolVersion },
  };
};

export const exportOutputs: CapabilityOperationFn = async (ctx) => {
  const p = ctx.project;
  const id = ctx.module.id;
  const paths = nativePaths(ctx.module.native, id);
  if (!existsSync(join(p.root, paths.script)) || !existsSync(join(p.root, paths.job))) return { status: "failed", summary: `${id} has no native design in ${ctx.module.native}/; run cad:generate first` };
  const source = readJson<{ script: string; job: string }>(join(p.root, paths.source));
  const now = { script: sha(readFileSync(join(p.root, paths.script))), job: sha(readFileSync(join(p.root, paths.job))) };
  let rebuilt = false;
  if (!source || source.script !== now.script || source.job !== now.job || !existsSync(join(p.root, paths.report))) {
    const b = await buildNative(ctx);
    if (!b.report) return { status: "failed", summary: `${id}: building the native design failed: ${b.error}` };
    rebuilt = true;
  }
  const report = readJson<Report>(join(p.root, paths.report))!;
  const job = readJson<Job>(join(p.root, paths.job))!;
  const from = (f: string) => readFileSync(join(p.root, paths.build, f));
  const out = ctx.module.out;
  for (const f of ["body.step", "body.glb", "body.manifest.json"]) ctx.writeOutput(`${out}/${f}`, from(f), `${id}: ${f}`);
  if (existsSync(join(p.root, paths.build, "section.svg"))) ctx.writeOutput(`${out}/section.svg`, from("section.svg"), `${id}: section through the cavity`);
  const parts = Object.keys(report.parts);
  for (const c of Object.values(report.covers ?? {})) {
    for (const fmt of ["step", "glb", "dxf"]) ctx.writeOutput(`${out}/${c.part}.${fmt}`, from(`covers/${c.part}.${fmt}`), `${id}: ${c.part} (${fmt.toUpperCase()}${fmt === "dxf" ? ", outline for cutting" : ""})`);
  }
  if (job.process === "print") {
    for (const part of parts) {
      ctx.writeOutput(`${out}/${part}.stl`, from(`parts/${part}.stl`), `${id}: ${part} for printing (STL)`);
      ctx.writeOutput(`${out}/${part}.3mf`, from(`parts/${part}.3mf`), `${id}: ${part} for printing (3MF)`);
    }
  }
  return { status: "succeeded", summary: `${id}: body STEP/GLB/manifest${job.process === "print" ? ` and STL + 3MF for ${parts.join(", ")}` : ""} in ${out}/${rebuilt ? " (rebuilt from the edited native design)" : ""}`, data: { parts, rebuilt } };
};

export const extract: CapabilityOperationFn = (ctx) => {
  const p = ctx.project;
  const id = ctx.module.id;
  const paths = nativePaths(ctx.module.native, id);
  const report = readJson<Report>(join(p.root, paths.report));
  if (!report) return { status: "failed", summary: `${id} has no built design (${paths.report}); run cad:generate` };
  const interfaces = new Set(ctx.module.definition.interfaces.map((i) => i.id));
  const frames = Object.fromEntries(Object.entries(report.features).filter(([fid, f]) => interfaces.has(fid) && f.frame).map(([fid, f]) => [fid, f.frame!]));
  const out = ctx.module.out;
  const have = (f: string) => existsSync(join(p.root, f));
  const artifacts: ArtifactDef[] = [{ id: "cad_source", name: `${id} build123d design`, type: "cad", role: "source", format: "build123d", filePath: ctx.module.native }];
  const prov = { tool: "build123d", toolVersion: report.toolVersion, sourceDigest: report.sourceDigest };
  if (have(`${out}/body.step`)) {
    artifacts.push(
      { id: "cad_step", name: `${id} body`, type: "cad", role: "body", format: "step", units: "mm", filePath: `${out}/body.step`, provenance: { generatedFrom: "cad_source", ...prov } },
      { id: "cad_glb", name: `${id} body (GLB)`, type: "cad", role: "body", format: "glb", units: "mm", filePath: `${out}/body.glb`, provenance: { generatedFrom: "cad_step", ...prov } },
      { id: "cad_manifest", name: `${id} geometry manifest`, type: "cad", format: "json", filePath: `${out}/body.manifest.json`, provenance: { generatedFrom: "cad_step", ...prov } },
    );
    for (const part of Object.keys(report.parts)) {
      for (const fmt of ["stl", "3mf"]) {
        if (have(`${out}/${part}.${fmt}`)) artifacts.push({ id: `${part}_${fmt}`, name: `${part} (${fmt.toUpperCase()}, for printing)`, type: "cad", role: "body", format: fmt, units: "mm", filePath: `${out}/${part}.${fmt}`, tags: ["manufacturing", "print"], provenance: { generatedFrom: "cad_step", ...prov } });
      }
    }
  }
  // window covers are separate parts (cut, not printed): their artifacts are for the modules that stand for them
  // (coverArtifacts in lib/), not the case's
  const covers = Object.fromEntries(
    Object.entries(report.covers ?? {}).map(([fid, c]) => [fid, { ...c, artifacts: coverArtifacts(out, fid).filter((a) => have(a.filePath!)).map((a) => ({ ...a, provenance: { ...a.provenance, ...prov } })) }]),
  );
  const facts: ExtractedFacts & { covers: typeof covers } = { frames, artifacts, covers };
  const missing = [...interfaces].filter((i) => !frames[i] && ctx.module.definition.interfaces.find((x) => x.id === i)?.traits?.some((t) => t.type === "enclosure_feature"));
  return {
    status: "succeeded",
    summary: `${id}: ${Object.keys(frames).length} frame(s), ${artifacts.length} artifact(s)${have(`${out}/body.step`) ? "" : " (not exported yet: native source only)"}${missing.length ? `; no frame for ${missing.join(", ")}` : ""}`,
    data: facts,
  };
};

export const check: CapabilityOperationFn = async (ctx) => {
  const p = ctx.project;
  const def = ctx.module.definition;
  const binding = { constraints: ctx.constraints, process: ctx.process, native: ctx.module.native, module: def.id, instances: ctx.module.instances };
  const current = buildJob(p, binding, def, ctx.module.instance);
  const paths = nativePaths(ctx.module.native, def.id);
  const refit = async (): Promise<Fit | { error: string }> => {
    const report = readJson<Report>(join(p.root, paths.report));
    const job = current.job;
    if (!report || !job) return { error: "no current job" };
    // the parts as built: the exported body (one node per part) when there is one, else the native build
    const body = `${ctx.module.out}/body.glb`;
    const byNode = existsSync(join(p.root, body));
    const glb = (part: string) => (byNode ? body : `${paths.build}/parts/${part}.glb`);
    const partNames = Object.keys(report.parts);
    if (!byNode && partNames.some((k) => !existsSync(join(p.root, glb(k))))) return { error: `neither ${body} nor ${paths.build}/parts/ is there to analyse; run cad:export` };
    const zones: Record<string, unknown[]> = {};
    for (const f of job.features.filter((x) => x.kind === "boss")) {
      const g = report.features[f.id];
      if (!g) continue;
      const top = g.top_z as number;
      for (const key of f.mates ?? []) zones[key] = [...(zones[key] ?? []), ...(g.holes as number[][]).map((h) => ({ centre: h, radius: (g.boss_d_mm as number) / 2 + job.design.clearance + 0.5, z: [top - 1, top + 1] }))];
    }
    const res = job.design.resolution;
    const plungers = Object.entries(report.features)
      .filter(([, g]) => g.kind === "button" && partNames.includes(g.plunger as string))
      .map(([fid, g]) => ({
        key: g.plunger as string,
        feature: fid,
        glb: glb(g.plunger as string),
        zones: [{ centre: g.tip, axis: g.frame?.normal, radius: (g.shaft_d_mm as number) / 2 + 0.01, z: [-0.01, (g.gap_mm as number) + res] }],
      }));
    const spec = {
      root: p.root,
      by_node: byNode,
      parts: Object.fromEntries(partNames.filter((k) => !k.startsWith("plunger")).map((k) => [k, glb(k)])),
      plungers,
      contents: job.contents,
      zones,
      cavity: report.cavity,
      resolution: job.design.resolution,
      clearance: job.design.clearance,
    };
    // the spec goes in on stdin: check is pure and writes nothing
    const r = await runPython([join(PY_DIR, "enclosure_cad.py"), "fit", "-"], p.root, JSON.stringify(spec));
    return r.ok ? (JSON.parse(r.stdout.trim().split("\n").pop()!) as Fit) : { error: r.error };
  };
  const diagnostics = await checkEnclosure({ p, def, native: ctx.module.native, config: `${ctx.module.dir}/cad.config.ts`, current, refit });
  const n = (s: string) => diagnostics.filter((d) => d.severity === s).length;
  return { status: "succeeded", summary: `${def.id}: ${n("error")} error(s), ${n("warning")} warning(s)`, diagnostics };
};
